// The packed font blobs, generated by `tools/fonttool` from the upstream
// typefaces and committed as assets. Each `include_bytes!` is validated by
// `Font::parse` at runtime, so a truncated or stale blob fails cleanly.

/// Sarasa Mono SC — the terminal font.
pub static SARASA_MONO: &[u8] = include_bytes!("../assets/sarasa-mono.velafont");

/// Source Sans 3 — the proportional UI font.
pub static SOURCE_SANS: &[u8] = include_bytes!("../assets/source-sans.velafont");

/// Iosevka — the narrow coding font.
pub static IOSEVKA: &[u8] = include_bytes!("../assets/iosevka.velafont");
